import '@kerfjs/ui/sidebar.css';
import '@kerfjs/ui/layout.css';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { Folder, Inbox } from 'lucide';

export const ProjectSidebar = () => <aside class="project-sidebar kui-sidebar kui-layout" aria-label="Project navigation">
  <div class="project-sidebar__body kui-scroll-owner">
    <section class="kui-sidebar-section"><MenuHeader label="Your work" /><MenuItem action="open-inbox" itemId="inbox" label="Inbox" selected leading={<LucideIcon icon={Inbox} name="inbox" />} /><MenuItem action="open-drafts" itemId="drafts" label="Drafts" /><MenuItem action="open-archive" itemId="archive" label="Archive" disabled /></section>
    <section class="kui-sidebar-section"><MenuHeader label="Projects" /><MenuItem action="open-project" itemId="launch" label="Launch plan" leading={<LucideIcon icon={Folder} name="folder" />} /><MenuItem action="open-project" itemId="research" label="Research" /></section>
    <section class="kui-sidebar-surface project-sidebar__summary" aria-label="Workspace summary"><strong>Design workspace</strong><span>12 open items · 3 due this week</span></section>
  </div>
  <footer class="project-sidebar__footer kui-control-cluster"><button type="button" data-action="invite">Invite</button><button type="button" data-action="settings">Settings</button></footer>
</aside>;

