.project-sidebar { display: grid; grid-template-rows: minmax(0, 1fr) auto; min-height: 0; }
.project-sidebar__summary { display: grid; gap: var(--kui-layout-metadata-gap); }
.project-sidebar__summary span { color: var(--kui-color-text-quiet); }
.project-sidebar__footer { padding: var(--kui-layout-pane-inset); border-block-start: 1px solid var(--kui-color-border); }
